contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner, address anotherOwner) public {
        require(newOwner != address(0));
        require(anotherOwner != newOwner);

        address beforeOwner = c.owner();

        bool firstReverted;
        bool firstSuccess;
        try c.setOwner(newOwner) returns (bool success) {
            firstReverted = false;
            firstSuccess = success;
        } catch {
            firstReverted = true;
        }

        if (!firstReverted) {
            assert(firstSuccess);
            assert(c.owner() == newOwner);

            bool secondReverted;
            try c.setOwner(anotherOwner) returns (bool success) {
                secondReverted = false;
                assert(success);
            } catch {
                secondReverted = true;
            }

            assert(!secondReverted);
            assert(c.owner() == anotherOwner);
            assert(c.owner() != beforeOwner);
        }
    }
}

